DROP TABLE IF EXISTS `lms_lessons`;
CREATE TABLE `lms_lessons` (
  `id` int NOT NULL AUTO_INCREMENT,
  `module_id` int NOT NULL,
  `title` varchar(150) NOT NULL,
  `description` text,
  `is_active` tinyint(1) DEFAULT '1',
  `last_modified_by` int DEFAULT NULL,
  `last_modified_at` timestamp NULL DEFAULT NULL,
  `video_type` enum('youtube', 'vimeo', 'panda', 'hostinger') DEFAULT 'youtube',
  `video_ref` varchar(255) DEFAULT NULL,
  `thumbnail_ref` varchar(255) DEFAULT NULL,
  `file_path` varchar(255) DEFAULT NULL COMMENT 'Internal full path for Hostinger',
  `file_size` bigint DEFAULT '0',
  `duration_seconds` int DEFAULT '0',
  `attachment_count` int DEFAULT '0',
  `display_order` int DEFAULT '0',
  `thumbnail_base64` longtext,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
